from .logger_handler import logger_handler


def _get_function_name(func):
    return func.__name__.capitalize().replace("_", " " )


def _get_exception_repr(exception):
    return exception.__repr__().replace(",", "")


def log_name(level="INFO"):
    def outer_wrapper(func):
        def inner_wrapper(*args, **kwargs):
            log_kwargs = {"also_console" : True} if level == "INFO" else {}
            logger_handler("Started:   {}".format(_get_function_name(func)), level=level, **log_kwargs)
            try:
                func(*args, **kwargs)
                logger_handler("Finished:  {}".format(_get_function_name(func)), level=level)
            except Exception as e:
                logger_handler("Exception: Function {} raised {}".format(_get_function_name(func), _get_exception_repr(e)), level="ERROR")
                raise

        return inner_wrapper

    return outer_wrapper
